package com.library.controller; import com.library.common.annotation.RequireRole; import com.library.common.constant.RoleConstant; import com.library.common.model.*; import com.library.model.entity.Notice; import com.library.service.NoticeService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/notices") public class NoticeController {private final NoticeService service;public NoticeController(NoticeService service){this.service=service;} @GetMapping("/public") public ApiResult<List<Notice>> publicList(){return ApiResult.success(service.publicList());} @GetMapping @RequireRole(RoleConstant.ADMIN) public ApiResult<PageResult<Notice>> page(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int size){return ApiResult.success(service.page(page,size));} @PostMapping @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> save(@RequestBody Notice x){service.save(x);return ApiResult.success();} @PutMapping @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> update(@RequestBody Notice x){service.update(x);return ApiResult.success();} @DeleteMapping("/{id}") @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> delete(@PathVariable Long id){service.delete(id);return ApiResult.success();}}
